<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { useToast } from 'vue-toastification'
import AppDropdownActions from '@/components/global/AppDropdownActions.vue'
import WorkflowActionDialog from '@/components/pages/workflows/WorkflowActionDialog.vue'
import { Workflow, ChevronRight, Clock3, CalendarDays, Activity } from 'lucide-vue-next'
import api from '@/api/workflows'
import AppTableList from '@/components/global/AppTableList.vue'
import AppButton from '@/components/global/AppButton.vue'
import StyledSelect from '@/components/global/StyledSelect.vue'
import AppDateRangePicker from '@/components/global/AppDateRangePicker.vue'
import AppSkeleton from '@/components/global/AppSkeleton.vue'
import AppEmptyState from '@/components/global/AppEmptyState.vue'
import emptySvg from '@/assets/illustrations/workflows-empty.svg?raw'
import { useWorkflowPolling } from '@/composables/useWorkflowPolling'
import { runStatusLabels as labels, formatRunDate as date } from '@/utils/workflowRuns'
const props = defineProps({ appointmentId: String, definitionId: String, compact: Boolean })
const emit = defineEmits(['select', 'active-count', 'definition-change'])
const router = useRouter(), toast = useToast(), cancelTarget = ref(null)
const page = ref(1), status = ref(''), workflow = ref(props.definitionId || ''), period = ref(null), definitions = ref([])
watch(() => props.definitionId, value => { workflow.value = value || '' })
watch([status, workflow, period, () => props.appointmentId], () => { page.value = 1 })
const params = computed(() => {
  const result = { page: page.value, limit: 10 }
  if (status.value) result.status = status.value
  if (workflow.value) result.definitionId = workflow.value
  if (props.appointmentId) result.appointmentId = props.appointmentId
  if (period.value?.[0] && period.value?.[1]) {
    const end = new Date(period.value[1]); end.setHours(23, 59, 59, 999)
    const start = new Date(period.value[0]); start.setHours(0, 0, 0, 0)
    result.from = start.toISOString(); result.to = end.toISOString()
  }
  return result
})
const { data, loading, error, refresh } = useWorkflowPolling(() => JSON.stringify(params.value), async () => (await api.getRuns(params.value)).data.data)
watch(() => data.value?.activeCount, count => { if (count !== undefined) emit('active-count', count) })
watch(() => data.value?.pagination.pages, pages => { if (pages && page.value > pages) page.value = pages })
const statuses = Object.entries(labels).filter(([value]) => !['pending', 'success', 'skipped'].includes(value)).map(([value, label]) => ({ value, label }))
const workflowOptions = computed(() => [{ value: '', label: 'Todos os workflows' }, ...definitions.value.map(d => ({ value: d._id, label: d.name })), ...(workflow.value && !definitions.value.some(d => d._id === workflow.value) ? [{ value: workflow.value, label: 'Workflow selecionado' }] : [])])
onMounted(async () => { try { definitions.value = (await api.getWorkflows()).data.data.definitions || [] } catch { /* Runs remain available when the definitions filter fails. */ } })
watch([workflow, workflowOptions], () => emit('definition-change', { id: workflow.value, name: workflowOptions.value.find(option => option.value === workflow.value)?.label || 'Fluxo selecionado' }), { immediate: true })
defineExpose({ refresh })
function viewDefinition(run) { router.push({ name: 'workflow-runs', query: { definitionId: run.definitionId } }) }
async function canceledDefinition({ canceledCount }) { cancelTarget.value = null; toast.success(`${canceledCount} execução(ões) cancelada(s).`); await refresh() }
function clear() { status.value = ''; workflow.value = ''; period.value = null }
</script>
<template>
  <AppTableList class="execution-table" :class="{ compact }" :pagination="data?.pagination || {}" @page-change="page = $event">
    <template #filters><div class="run-filters"><StyledSelect v-model="workflow" :options="workflowOptions" placeholder="Workflow" /><StyledSelect v-model="status" :options="[{ value: '', label: 'Todos os status' }, ...statuses]" placeholder="Status" /><AppDateRangePicker v-model="period" clearable /><AppButton variant="outline" @click="clear">Limpar</AppButton></div></template>

    <template v-if="loading"><div class="results-scroll skeleton-desktop" aria-label="Carregando execuções" aria-busy="true"><table class="runs-grid"><colgroup><col class="col-workflow" /><col class="col-patient" /><col class="col-status" /><col class="col-stage" /><col class="col-activity" /><col class="col-actions" /></colgroup><thead><tr><th>Workflow</th><th>Paciente / atendimento</th><th>Status</th><th>Etapas atuais</th><th>Atividade</th><th>Ações</th></tr></thead><tbody><tr v-for="n in 7" :key="n"><td><div class="workflow-cell"><AppSkeleton width="34px" height="34px" border-radius="9px" /><AppSkeleton width="65%" height="14px" /></div></td><td><AppSkeleton width="80%" height="14px" /><AppSkeleton width="65%" height="11px" /></td><td><AppSkeleton width="75px" height="23px" border-radius="20px" /></td><td><AppSkeleton width="85%" height="13px" /><AppSkeleton width="55%" height="11px" /></td><td><AppSkeleton width="85%" height="13px" /><AppSkeleton width="70%" height="11px" /></td><td><AppSkeleton width="100%" height="30px" border-radius="7px" /></td></tr></tbody></table></div><div class="skeleton-cards" aria-label="Carregando execuções" aria-busy="true"><article v-for="n in 4" :key="n"><div class="workflow-cell"><AppSkeleton width="34px" height="34px" border-radius="9px" /><AppSkeleton width="60%" height="14px" /></div><AppSkeleton width="65%" height="14px" /><AppSkeleton width="85%" height="32px" border-radius="7px" /><AppSkeleton width="75%" height="12px" /><AppSkeleton width="110px" height="30px" border-radius="7px" /></article></div></template>
    <template v-else>
      <div v-if="error" class="run-error" role="alert">{{ error }} <AppButton variant="outline" @click="refresh">Tentar novamente</AppButton></div>
      <div v-if="data && !data.runs.length" class="list-state"><AppEmptyState title="Nenhuma execução encontrada" text="As execuções aparecerão aqui. Se houver filtros, ajuste-os para consultar outro período."><template #illustration><div class="empty-art" aria-hidden="true" v-html="emptySvg"></div></template></AppEmptyState></div>
      <div v-else-if="data" class="results-scroll">
        <table class="runs-grid"><caption class="sr-only">Execuções de workflows</caption><colgroup><col class="col-workflow" /><col class="col-patient" /><col class="col-status" /><col class="col-stage" /><col class="col-activity" /><col class="col-actions" /></colgroup><thead><tr><th>Workflow</th><th>Paciente / atendimento</th><th>Status</th><th>Etapas atuais</th><th>Atividade</th><th>Ações</th></tr></thead><tbody><tr v-for="run in data.runs" :key="run._id"><td><div class="workflow-cell"><span class="run-card-icon"><Workflow :size="18" /></span><strong :title="run.workflowName">{{ run.workflowName }}</strong></div></td><td><div class="patient-cell"><span :title="run.patientName">{{ run.patientName || 'Não informado' }}</span><small v-if="run.appointment"><CalendarDays :size="12" />{{ date(run.appointment.startTime) }}</small></div></td><td><span class="run-status" :class="run.status">{{ labels[run.status] }}</span></td><td><span class="stage-cell">{{ run.currentNodes.map(n => n.label).join(', ') || '—' }}</span></td><td><div class="activity-cell"><span>{{ date(run.lastActivityAt) }}</span><small>Início: {{ date(run.startedAt) }}</small></div></td><td><div class="run-row-actions"><AppButton variant="outline" size="sm" @click="emit('select', run._id)">Ver detalhes</AppButton><AppDropdownActions menu-width="260px"><template #default="{ close }"><button class="dropdown-item" @click="close(); viewDefinition(run)"><Workflow :size="14" />Ver execuções deste fluxo</button><button class="dropdown-item delete" @click="close(); cancelTarget = { id: run.definitionId, name: run.workflowName }"><Activity :size="14" />Cancelar todas as execuções</button></template></AppDropdownActions></div></td></tr></tbody></table>
        <div class="run-cards"><article v-for="run in data.runs" :key="run._id"><div class="run-card-heading"><span class="run-card-icon"><Workflow :size="18" /></span><strong>{{ run.workflowName }}</strong><span class="run-status" :class="run.status">{{ labels[run.status] }}</span></div><div class="run-card-subject"><span>{{ run.patientName || 'Paciente não informado' }}</span><small v-if="run.appointment"><CalendarDays :size="13" />{{ date(run.appointment.startTime) }}</small></div><div class="run-card-stage"><Activity :size="14" /><span>{{ run.currentNodes.map(n => n.label).join(', ') || 'Nenhuma etapa em andamento' }}</span></div><div class="run-card-dates"><div><span>Início</span><small>{{ date(run.startedAt) }}</small></div><div><span>Última atividade</span><small>{{ date(run.lastActivityAt) }}</small></div></div><div class="run-card-footer"><AppDropdownActions menu-width="260px"><template #default="{ close }"><button class="dropdown-item" @click="close(); viewDefinition(run)"><Workflow :size="14" />Ver execuções deste fluxo</button><button class="dropdown-item delete" @click="close(); cancelTarget = { id: run.definitionId, name: run.workflowName }"><Activity :size="14" />Cancelar todas as execuções</button></template></AppDropdownActions><AppButton variant="outline" size="sm" @click="emit('select', run._id)">Ver detalhes<ChevronRight :size="14" /></AppButton></div></article></div>
      </div>
    </template>
  </AppTableList><WorkflowActionDialog v-if="cancelTarget" action="cancel_runs" :ids="[cancelTarget.id]" :workflow-name="cancelTarget.name" @close="cancelTarget = null" @complete="canceledDefinition" />
</template>
<style scoped>
