:12px;padding:12px}@media(max-width:768px){.execution-table :deep(.summary-text){display:none}.execution-table :deep(.pagination-navigation>.btn-nav:first-child),.execution-table :deep(.pagination-navigation>.btn-nav:last-child){display:none}table{display:none}.run-cards{display:grid}.run-filters>*{flex:1}.execution-table :deep(.filters-header){flex-wrap:wrap}}
.run-cards article{display:block;padding:16px;border-radius:12px;box-shadow:0 1px 2px #0f172a03}.run-card-heading{display:flex;align-items:center;gap:9px}.run-card-heading>strong{flex:1;min-width:0;font-size:.875rem;font-weight:600;color:#111827}.run-card-icon{display:flex;align-items:center;justify-content:center;width:34px;height:34px;flex-shrink:0;border-radius:9px;background:#eff6ff;color:#2563eb}.run-card-heading .run-status{font-size:.68rem;font-weight:500}.run-card-subject{margin:12px 0;color:#475569;font-size:.8rem}.run-card-subject>small{display:flex;align-items:center;gap:5px;font-size:.7rem;margin-top:4px}.run-card-stage{display:flex;align-items:center;gap:7px;padding:9px 10px;border-radius:7px;background:#f8fafc;color:#64748b;font-size:.75rem}.run-card-stage svg{flex-shrink:0;color:#94a3b8}.run-card-dates{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:12px 0}.run-card-dates>div>span{color:#94a3b8;font-size:.65rem}.run-card-dates small{font-size:.7rem;color:#475569;margin-top:3px}.run-card-footer{display:flex;justify-content:flex-end;padding-top:10px;border-top:1px solid #f1f5f9}.compact .run-filters{display:grid;grid-template-columns:1fr 1fr;gap:8px}.compact .run-filters>*{min-width:0}.compact :deep(.filters-header){padding:14px 16px;border-color:#e5e7eb}.compact .run-cards{padding:16px;gap:12px}.compact :deep(.pagination-container){background:transparent;border-color:#e5e7eb}@media(max-width:480px){.run-card-heading{flex-wrap:wrap}.run-card-heading>strong{min-width:calc(100% - 44px)}.run-card-heading .run-status{margin-left:43px}.run-card-dates{grid-template-columns:1fr}.compact .run-cards{padding:12px}.compact :deep(.filters-header){padding:12px}}
.runs-grid{table-layout:fixed;min-width:1120px}.col-workflow{width:19%}.col-patient{width:20%}.col-status{width:10%}.col-stage{width:19%}.col-activity{width:18%}.col-actions{width:14%}.runs-grid .run-status{font-size:.7rem}.runs-grid td{min-width:0;padding:16px}.runs-grid th{padding-left:16px;padding-right:16px}.workflow-cell{display:flex;align-items:center;gap:10px;min-width:0}.workflow-cell>strong{font-size:.8125rem;font-weight:600;color:#334155;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.patient-cell>span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.8125rem}.patient-cell small{display:flex;align-items:center;gap:5px;font-size:.7rem}.stage-cell{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:.75rem;line-height:1.5;color:#64748b}.activity-cell>span{font-size:.75rem;color:#334155}.activity-cell>small{font-size:.68rem;color:#94a3b8}.run-row-actions{display:flex;align-items:center;justify-content:flex-end;gap:5px}.run-row-actions .app-button{font-size:.7rem;white-space:nowrap}.run-card-footer{justify-content:space-between}.skeleton-desktop :deep(.app-skeleton){margin:5px 0;flex-shrink:0}.skeleton-cards{display:none;overflow:auto;min-height:0;padding:16px;gap:12px}.skeleton-cards article{display:grid;gap:14px;padding:16px;background:white;border:1px solid #e5e7eb;border-radius:12px}.compact .skeleton-desktop{display:none}.compact .skeleton-cards{display:grid}@media(max-width:768px){.skeleton-desktop{display:none}.skeleton-cards{display:grid}}
</style>
